#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1 << 19 | 5;
int n, k, p, max_bit, count[MAXN], f[MAXN];
int tmp1[20][MAXN], tmp2[20][MAXN], tmp3[20][MAXN];
long long p_pow;
long long t[20][MAXN];
long long fact[MAXN], inv_fact[MAXN];

long long qpow(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp > 0) {
        if (exp & 1) res = res * cur % p;
        cur = cur * cur % p;
        exp >>= 1;
    }
    return res;
}

void prepare() {
    fact[0] = 1;
    for (int i = 1; i <= max_bit; i++)
        fact[i] = fact[i - 1] * i % p;
    inv_fact[max_bit] = qpow(fact[max_bit], p - 2);
    for (int i = max_bit - 1; i >= 0; i--)
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % p;
}

int get_lower(int x) {
    int res = 1;
    while (res < x) res <<= 1;
    return res;
}

void FWT_transform(int *arr, int len, bool inv = false) {
    long long *temp = t[0];
    for (int i = 0; i < len; i++) temp[i] = arr[i];
    if (inv)
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] -= temp[k];
    else
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] += temp[k];
    for (int i = 0; i < len; i++) {
        arr[i] = temp[i] % p;
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void mod_adjust(long long &x) { x >= p_pow ? x -= p_pow : x; }

void multiply() {
    for (int j = 0; j <= 19; j++) {
        memset(tmp1[j], 0, sizeof(int[max_bit + 1]));
        memset(t[j], 0, sizeof(long long[max_bit + 1]));
    }
    for (int j = 0; j <= max_bit; j++)
        tmp1[count[j]][j] = f[j];
    for (int j = 0; j <= 19; j++)
        FWT_transform(tmp1[j], max_bit + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_bit; s++)
                mod_adjust(t[q + l][s] += 1LL * tmp1[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_bit; s++)
            tmp3[q][s] = t[q][s] % p;
    for (int j = 0; j <= 19; j++)
        FWT_transform(tmp3[j], max_bit + 1, true);
    for (int j = 0; j <= max_bit; j++)
        f[j] = tmp3[count[j]][j];
}

void multiply_alt() {
    static int tmp[20][MAXN];
    for (int i = 0; i <= 19; i++)
        memset(t[i], 0, sizeof(long long[max_bit + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_bit; s++)
                mod_adjust(t[q + l][s] += 1LL * tmp2[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_bit; s++)
            tmp[q][s] = t[q][s] % p;
    for (int i = 0; i <= 19; i++)
        FWT_transform(tmp[i], max_bit + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2[i], 0, sizeof(int[max_bit + 1]));
    for (int i = 0; i <= max_bit; i++)
        tmp2[count[i]][i] = tmp[count[i]][i];
    for (int i = 0; i <= 19; i++)
        FWT_transform(tmp2[i], max_bit + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    p_pow = 1LL * p * p;
    if (n & 1) {
        printf("%lld", qpow(k, n));
        return 0;
    }
    f[0] = 1;
    max_bit = get_lower(n + 1) - 1;
    prepare();
    for (int i = 0; i <= max_bit; i++)
        count[i] = __builtin_popcount(i);
    for (int i = 0; i <= max_bit; i++)
        tmp2[count[i]][i] = inv_fact[i];
    for (int i = 0; i <= 19; i++)
        FWT_transform(tmp2[i], max_bit + 1);
    int res_k = k;
    while (k) {
        if (k & 1) multiply();
        k >>= 1;
        if (k) multiply_alt();
    }
    printf("%lld", (qpow(res_k, n) - fact[n] * f[n] % p + p) % p);
    return 0;
}
